/* ===== CSS block berikutnya dari dokumen asli ===== */

/* Layout: sidebar + one-screen chat column. Emily is a set of expression sprites (cut from the character sheet) that crossfade with the chat state: stage hero before the first message, a small figure peeking over the input bar afterwards. */
:root {
  --bg: #faf7f6;
  --side: #f3eeed;
  --panel: #efe7e6;
  --card: #fffdfc;
  --ink: #4a3f40;
  --muted: #8c7f80;
  --accent: #9a7e80;
  --accent-ink: #ffffff;
  --line: rgba(120, 96, 98, 0.16);
  --spark: #e6d3d2;
  --shadow: 0 8px 28px rgba(120, 90, 92, 0.12);
  --arch: #f0e8e7;
  --sp-filter: none;
  --danger: #a4585c;
  --font-display: "Cormorant Garamond", Georgia, "Times New Roman", serif;
  --font-body: "Nunito", system-ui, -apple-system, "Segoe UI", sans-serif;
  --gl: max(16px, env(safe-area-inset-left, 0px));
  --gr: max(16px, env(safe-area-inset-right, 0px));
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #1d1819; --side: #231d1e; --panel: #2f2627; --card: #271f20;
    --ink: #ece0e0; --muted: #a99a9b; --accent: #b8999b; --accent-ink: #231a1b;
    --line: rgba(240, 220, 220, 0.14); --spark: #4a3c3e;
    --shadow: 0 8px 28px rgba(0, 0, 0, 0.35); --danger: #e08f93;
    --arch: #2b2324; --sp-filter: invert(1) hue-rotate(180deg);
    color-scheme: dark;
  }
}
:root[data-theme="dark"] {
  --bg: #1d1819; --side: #231d1e; --panel: #2f2627; --card: #271f20;
  --ink: #ece0e0; --muted: #a99a9b; --accent: #b8999b; --accent-ink: #231a1b;
  --line: rgba(240, 220, 220, 0.14); --spark: #4a3c3e;
  --shadow: 0 8px 28px rgba(0, 0, 0, 0.35); --danger: #e08f93;
  --arch: #2b2324; --sp-filter: invert(1) hue-rotate(180deg);
  color-scheme: dark;
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.5;
  overflow: hidden;
}
button, input, select, textarea { font: inherit; color: inherit; }
button { cursor: pointer; }
a { color: inherit; text-decoration: none; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
svg.i { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }

.app { display: grid; grid-template-columns: clamp(200px, 22vw, 320px) minmax(0, 1fr); height: 100%; }

/* Sidebar */
.side {
  background: var(--side);
  display: flex; flex-direction: column;
  padding-block: 28px 28px;
  padding-left: var(--gl);
  padding-right: 20px;
  min-height: 0;
}
.brand { display: flex; align-items: center; gap: 10px; padding: 0 6px 30px; font-family: var(--font-display); font-size: 31px; font-weight: 500; letter-spacing: 0.01em; line-height: 1; }
.brand svg.i { width: 34px; height: 34px; stroke-width: 1.5; color: var(--ink); }
.brand .spk { width: 16px; height: 16px; fill: var(--spark); margin-left: 2px; animation: twinkle 3.4s ease-in-out infinite; }
.nav { padding-top: 28px; display: flex; flex-direction: column; gap: 10px; }
.nav a { display: flex; align-items: center; gap: 16px; padding: 15px 20px; border-radius: 22px; color: var(--muted); font-size: 18px; transition: background .18s, color .18s, transform .18s; }
.nav a:hover { color: var(--ink); transform: translateX(3px); }
.nav a[aria-current="page"] { background: var(--panel); color: var(--ink); }
.talk {
  margin-top: auto; text-align: left; border: 0; border-radius: 20px;
  background: var(--panel); padding: 16px 18px; display: flex; gap: 14px; align-items: center; position: relative;
  transition: transform .18s;
}
.talk:hover { transform: translateY(-2px); }
.talk svg.heart { width: 22px; height: 22px; fill: var(--accent); flex: none; animation: beat 2.6s ease-in-out infinite; }
.talk b { display: block; font-weight: 600; font-size: 15px; }
.talk i { display: block; font-family: var(--font-display); font-size: 15px; color: var(--muted); font-weight: 500; }

/* Main column */
.main { display: flex; flex-direction: column; min-width: 0; min-height: 0; padding-right: var(--gr); padding-left: 28px; }
.topbar { display: flex; align-items: center; justify-content: flex-end; gap: 10px; height: 84px; flex: none; }
.brand-m { display: none; margin-right: auto; align-items: center; gap: 8px; font-family: var(--font-display); font-size: 26px; font-weight: 500; }
.brand-m svg.i { width: 28px; height: 28px; stroke-width: 1.5; }
.ghost { border: 0; background: transparent; color: var(--ink); height: 44px; min-width: 44px; border-radius: 22px; display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 0 12px; }
.ghost:hover { background: var(--panel); }
.ghost.txt { font-size: 15px; color: var(--muted); }
#theme svg { transition: transform .4s cubic-bezier(.3,1.4,.5,1); }
#theme:hover svg { transform: rotate(40deg); }
.avatar-btn { width: 52px; height: 52px; border-radius: 50%; background: var(--panel); color: var(--muted); }
.avatar-btn svg.i { fill: currentColor; stroke: none; width: 24px; height: 24px; }
.views { flex: 1; min-height: 0; display: flex; flex-direction: column; }
.view { flex: 1; min-height: 0; display: flex; flex-direction: column; }
.view[hidden] { display: none; }

/* Emily: expression sprites */
.mascot { position: relative; display: block; border: 0; padding: 0; margin: 0; background: transparent; aspect-ratio: 600 / 520; filter: var(--sp-filter); -webkit-tap-highlight-color: transparent; }
.mp, .mb { position: absolute; inset: 0; transform-origin: 50% 100%; }
.mb { animation: bob 4.6s ease-in-out infinite; }
.mascot[data-mood="sleeping"] .mb, .mascot[data-mood="sleepy"] .mb { animation-duration: 7.5s; }
.mascot[data-mood="thinking"] .mb { animation: sway 2.8s ease-in-out infinite; }
.mascot[data-mood="angry"] .mb { animation: shake .5s ease-in-out 2; }
.sp { position: absolute; inset: 0; background-repeat: no-repeat; background-size: 100% 100%; background-position: 50% 100%; opacity: 0; transition: opacity .14s linear; }
.sp.on { opacity: 1; }
.mp.bump { animation: bump .38s cubic-bezier(.3, 1.5, .5, 1); }
.mp.hop { animation: hop .6s cubic-bezier(.3, .9, .4, 1); }

/* ===== Emily idle frames ===== */
.hero{visibility:hidden}.peek{display:none!important}.arch{display:none}
#roam{position:fixed;inset:0;pointer-events:none;z-index:30;overflow:hidden}
.pet{position:absolute;left:0;top:0;width:clamp(88px,9vw,110px);aspect-ratio:190/364;will-change:transform;pointer-events:none}
.pet::after{content:"";position:absolute;left:12%;right:12%;bottom:calc(4.4% - 4px);height:7px;border-radius:50%;background:radial-gradient(closest-side,rgba(60,50,50,.3),rgba(60,50,50,.1) 60%,transparent)}
.pet .fig{position:absolute;inset:0;pointer-events:none;transform-origin:50% 100%;filter:var(--sp-filter) drop-shadow(0 1.5px 2px rgba(90,70,70,.22))}
.pet .bob{position:absolute;inset:0;transform-origin:50% 100%;animation:breath 3.8s ease-in-out infinite}
.pet.drag .bob{transform-origin:50% 6%;animation:dang 1s ease-in-out infinite}
.spr{position:absolute;inset:0;width:100%;height:100%;display:none;pointer-events:auto;cursor:grab;-webkit-user-drag:none;user-select:none;touch-action:none}
.pet.drag .spr{cursor:grabbing}.spr.on{display:block}
.pet.hop .fig{animation:hopp .55s cubic-bezier(.3,.9,.4,1)}
.bub{position:absolute;left:50%;bottom:100%;margin-bottom:-2px;transform:translateX(-50%) scale(.6);background:var(--panel);color:var(--ink);border:1px solid var(--line);border-radius:14px;padding:4px 10px;font:600 12px var(--font-body);white-space:nowrap;opacity:0;transition:opacity .25s,transform .25s;box-shadow:var(--shadow)}
.bub::after{content:"";position:absolute;left:50%;bottom:-5px;width:8px;height:8px;background:var(--panel);border-right:1px solid var(--line);border-bottom:1px solid var(--line);transform:translateX(-50%) rotate(45deg)}
.bub.show{opacity:1;transform:translateX(-50%) scale(1)}
@keyframes breath{0%,100%{scale:1 1}50%{scale:1 1.012}}
@keyframes dang{0%,100%{rotate:-6deg}50%{rotate:6deg}}
@keyframes hopp{0%,100%{transform:translateY(0)}35%{transform:translateY(-24px)}}
@media (prefers-reduced-motion:reduce){.pet *{animation:none!important}}
.sugs{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}.sugs button{border:1px solid var(--line);background:var(--card);color:var(--ink);border-radius:999px;padding:7px 13px;font-size:14px;transition:transform .15s,background .15s}.sugs button:hover{transform:translateY(-2px);background:var(--arch)}
/* Stage */
.stage { position: relative; flex: 1; min-height: 0; display: flex; align-items: flex-end; justify-content: center; border-bottom: 1px solid var(--line); }
.hero-wrap { position: relative; flex: none; width: max(230px, min(500px, 100%, calc((100dvh - 290px) * 1.15))); }
.arch { position: absolute; left: 12%; right: 12%; bottom: 0; height: 88%; background: var(--arch); border-radius: 999px 999px 0 0 / 70% 70% 0 0; }
.hero { width: 100%; cursor: pointer; }
.hello {
  align-self: center; margin-bottom: 14%; margin-left: -4px;
  background: var(--panel); border-radius: 28px; padding: 22px 30px; max-width: 360px; position: relative;
  box-shadow: 0 1px 0 var(--line);
  transform-origin: 0% 70%;
  animation: popin .6s cubic-bezier(.2, 1.5, .4, 1) .3s both;
}
.hello::before { content: ""; position: absolute; left: -10px; bottom: 26px; width: 22px; height: 22px; background: var(--panel); clip-path: polygon(100% 0, 100% 100%, 0 100%); border-bottom-left-radius: 2px; }
.hello h1 { margin: 0 0 8px; font-size: 24px; font-weight: 700; line-height: 1.25; text-wrap: balance; animation: fadeup .5s ease-out .55s both; }
.hello p { margin: 0; font-size: 18px; color: var(--muted); line-height: 1.55; animation: fadeup .5s ease-out .8s both; }
.hello p + p { margin-top: 6px; animation-delay: 1.05s; }
.spark { position: absolute; width: 38px; height: 38px; fill: var(--spark); pointer-events: none; animation: twinkle 3.6s ease-in-out infinite; }

/* Messages */
.log { flex: 1; min-height: 0; overflow-y: auto; overflow-x: hidden; display: flex; flex-direction: column; gap: 16px; padding: 4px 4px 96px; scroll-behavior: smooth; }
.log[hidden] { display: none; }
.log > * { width: 100%; max-width: 820px; margin-inline: auto; }
.row { display: flex; gap: 12px; align-items: flex-end; min-width: 0; animation: rise .28s ease-out both; }
.row.me { justify-content: flex-end; }
.av { --av: 38px; width: var(--av); height: var(--av); border-radius: 50%; flex: none; background-color: var(--arch); background-repeat: no-repeat; background-size: 175% auto; background-position: 50% 92%; filter: var(--sp-filter); box-shadow: 0 0 0 1px var(--line); }
.bubble { max-width: min(600px, 86%); padding: 12px 18px; border-radius: 22px; background: var(--panel); white-space: pre-wrap; overflow-wrap: anywhere; min-width: 0; }
.row.me .bubble { background: var(--accent); color: var(--accent-ink); border-bottom-right-radius: 8px; }
.row.bot .bubble { border-bottom-left-radius: 8px; }
.bubble img { display: block; max-width: 100%; max-height: 220px; border-radius: 14px; margin-bottom: 8px; }
.dots { display: inline-flex; gap: 5px; padding: 6px 2px; }
.dots i { width: 7px; height: 7px; border-radius: 50%; background: var(--muted); animation: blink 1.2s infinite ease-in-out; }
.dots i:nth-child(2) { animation-delay: .15s; } .dots i:nth-child(3) { animation-delay: .3s; }
.note { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; justify-content: center; color: var(--danger); font-size: 14.5px; text-align: center; animation: rise .28s ease-out both; }
.note button { border: 1px solid var(--line); background: var(--card); border-radius: 16px; padding: 4px 14px; color: var(--ink); }

/* Composer */
.composer { flex: none; padding: 18px 0 22px; position: relative; }
.peek { display: none; position: absolute; right: 26px; bottom: calc(100% - 26px); width: 132px; z-index: 0; }
body[data-chatting] .peek { display: block; }
.chip { display: none; align-items: center; gap: 10px; margin: 0 8px 10px; padding: 6px 10px 6px 6px; background: var(--panel); border-radius: 16px; width: fit-content; max-width: 100%; font-size: 14px; color: var(--muted); position: relative; z-index: 1; }
.chip.on { display: flex; }
.chip img { width: 44px; height: 44px; object-fit: cover; border-radius: 10px; }
.chip button { border: 0; background: transparent; width: 28px; height: 28px; border-radius: 50%; color: var(--muted); font-size: 18px; line-height: 1; }
.pill { display: flex; align-items: center; gap: 10px; background: var(--card); border: 1px solid var(--line); border-radius: 44px; padding: 14px 18px 14px 22px; box-shadow: var(--shadow); position: relative; z-index: 1; transition: box-shadow .2s, border-color .2s; }
.pill:focus-within { border-color: var(--accent); }
.pill .clip { border: 0; background: transparent; color: var(--muted); width: 36px; height: 36px; border-radius: 50%; display: grid; place-items: center; }
.pill .clip:hover { color: var(--ink); background: var(--panel); }
.pill .clip[hidden] { display: none; }
.pill textarea { flex: 1; min-width: 0; border: 0; outline: 0; background: transparent; resize: none; font-size: 18px; line-height: 1.45; max-height: 130px; padding: 8px 0; }
.pill textarea::placeholder { color: var(--muted); opacity: .8; }
.send { width: 58px; height: 58px; border-radius: 50%; border: 0; background: var(--accent); color: var(--accent-ink); display: grid; place-items: center; flex: none; transition: transform .12s, opacity .15s; overflow: hidden; }
.send:hover { transform: scale(1.05); }
.send:active { transform: scale(.92); }
.send svg.i { width: 26px; height: 26px; }
.send.fly svg { animation: fly .55s ease-in-out; }
.send .stop { display: none; width: 18px; height: 18px; border-radius: 4px; background: currentColor; }
.send.busy svg { display: none; } .send.busy .stop { display: block; }

/* History + settings */
.page { flex: 1; min-height: 0; overflow-y: auto; padding: 4px 4px 28px; }
.page > * { max-width: 720px; margin-inline: auto; animation: fadeup .35s ease-out both; }
.page h2 { font-family: var(--font-display); font-size: 36px; font-weight: 600; margin: 0 0 18px; }
.list { display: flex; flex-direction: column; gap: 12px; }
.hist { display: flex; align-items: center; gap: 12px; background: var(--panel); border-radius: 22px; padding: 6px 8px 6px 6px; transition: transform .15s; }
.hist:hover { transform: translateY(-2px); }
.hist .open { flex: 1; min-width: 0; text-align: left; border: 0; background: transparent; padding: 12px 14px; border-radius: 18px; }
.hist .open b { display: block; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hist .open span { color: var(--muted); font-size: 14px; }
.hist .del { border: 0; background: transparent; color: var(--muted); width: 42px; height: 42px; border-radius: 50%; display: grid; place-items: center; }
.hist .del:hover { color: var(--danger); background: var(--card); }
.empty { text-align: center; color: var(--muted); padding: 36px 8px; display: flex; flex-direction: column; align-items: center; gap: 14px; }
.empty .av { --av: 96px; animation: bob 4.6s ease-in-out infinite; }
.btn { border: 0; border-radius: 22px; background: var(--accent); color: var(--accent-ink); padding: 10px 22px; font-weight: 600; }
.btn.alt { background: var(--panel); color: var(--ink); }
.btn.danger { background: transparent; color: var(--danger); border: 1px solid var(--danger); }
.form { background: var(--panel); border-radius: 26px; padding: 8px 24px; }
.field { display: flex; align-items: center; justify-content: space-between; gap: 18px; padding: 18px 0; border-bottom: 1px solid var(--line); flex-wrap: wrap; }
.field:last-child { border-bottom: 0; }
.field label, .field .lbl { font-weight: 600; }
.field small { display: block; color: var(--muted); font-weight: 400; font-size: 14px; }
.field input[type="text"], .field select { background: var(--card); border: 1px solid var(--line); border-radius: 16px; padding: 10px 14px; min-width: 0; width: 230px; max-width: 100%; }
.confirm { display: inline-flex; gap: 8px; align-items: center; flex-wrap: wrap; }

/* Motion */
@keyframes bob { 0%, 100% { transform: translateY(0) scaleY(1); } 50% { transform: translateY(-6px) scaleY(1.014); } }
@keyframes sway { 0%, 100% { transform: rotate(-1.6deg) translateY(0); } 50% { transform: rotate(1.6deg) translateY(-4px); } }
@keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-5px); } 75% { transform: translateX(5px); } }
@keyframes bump { 0% { transform: scale(.95, 1.04); } 55% { transform: scale(1.035, .98); } 100% { transform: scale(1); } }
@keyframes hop { 0%, 100% { transform: translateY(0) scale(1); } 30% { transform: translateY(-26px) scale(.98, 1.03); } 60% { transform: translateY(0) scale(1.04, .95); } 80% { transform: translateY(-5px); } }
@keyframes twinkle { 0%, 100% { opacity: .55; transform: scale(.82) rotate(0deg); } 50% { opacity: 1; transform: scale(1.1) rotate(14deg); } }
@keyframes beat { 0%, 100% { transform: scale(1); } 12% { transform: scale(1.22); } 24% { transform: scale(1); } 36% { transform: scale(1.14); } 48% { transform: scale(1); } }
@keyframes popin { from { opacity: 0; transform: scale(.7); } to { opacity: 1; transform: scale(1); } }
@keyframes fadeup { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
@keyframes rise { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
@keyframes blink { 0%, 80%, 100% { opacity: .25; transform: translateY(0); } 40% { opacity: 1; transform: translateY(-3px); } }
@keyframes fly { 0% { transform: none; opacity: 1; } 45% { transform: translate(18px, -18px); opacity: 0; } 46% { transform: translate(-18px, 18px); opacity: 0; } 100% { transform: none; opacity: 1; } }

